/**
 * KI Connect – Internationalization (i18n)
 * ==========================================
 * To add a new language:
 *   1. Copy an existing language block below, translate all values.
 *   2. Keep all keys identical to the English block.
 *   3. Add the new lang code to LANGUAGES.
 *
 * Load this file BEFORE kiconnect.html's main <script> block.
 */

