    'agent.confirmDeleteProject': '"{name}" திட்டத்தை KI Connect இலிருந்து உண்மையிலேயே அகற்ற வேண்டுமா?\n\nவட்டில் உள்ள கோப்புறையும் அதன் கோப்புகளும் தொடப்படாமல் இருக்கும் — இணைப்பு மட்டுமே அகற்றப்படும். இதனால் இந்தத் திட்டத்தில் உள்ள {n} அரட்டை(கள்) நிரந்தரமாக நீக்கப்படும் (மீட்டெடுக்க முடியாது).',
