    'agent.shellWarning': '"{name}" க்கான ஷெல் கட்டளைகளை இயக்க வேண்டுமா?\n\nஇதன் பிறகு முகவர் திட்டக் கோப்புறையில் எந்த டெர்மினல் கட்டளையையும் இயக்க முடியும் (எ.கா., தொகுப்புகளை நிறுவுதல், சோதனைகளை இயக்குதல், திட்டத்திற்கு வெளியே உள்ள கோப்புகளை நீக்குதல்). இது உங்கள் கணினியில் உள்ளூர் KI Connect சேவையகத்தின் அதே அனுமதிகளுடன் இயங்கும் — உண்மையான தனிமைப்படுத்தப்பட்ட சூழல் இல்லை, திட்டக் கோப்புறை மட்டுமே பணி அடைவாக உள்ளது.\n\nஇந்த திட்டத்தை நீங்கள் நம்பினால் மட்டுமே தொடரவும்.',
    'agent.sim.createDir': 'உருவகப்படுத்தல்: "{path}" கோப்புறை உருவாக்கப்பட்டிருக்கும்.',
    'agent.sim.deleteDir': 'உருவகப்படுத்தல்: "{path}" கோப்புறையும் அதன் உள்ளடக்கமும் நீக்கப்பட்டிருக்கும். எதுவும் மாற்றப்படவில்லை.',
